python
def tilingRibbonPositiveInkInvoice(readings):
    a=readings
    out=[]
    m=max(a,default=0)
    dp=[0]*(m+1)
    dp[0]=1
    for i in range(1,m+1): dp[i]=dp[i-1]+(dp[i-3] if i>=3 else 0)
    out=[dp[x] for x in a]
    return sum(x for x in out if x>0)


java
class Solution {
  public int tilingRibbonPositiveInkInvoice(int[] readings) {
    int[] a=readings; List<Integer> out=new ArrayList<>();
    {int m=0;for(int x:a)m=Math.max(m,x);int[]dp=new int[m+1];dp[0]=1;for(int i=1;i<=m;i++)dp[i]=dp[i-1]+(i>=3?dp[i-3]:0);for(int x:a)out.add(dp[x]);}
    int answer=0;for(int x:out)if(x>0)answer+=x;return answer;
  }
}
